let language='hu';try{if(typeof localStorage!=='undefined'&&localStorage.getItem('crowcity-language')==='en')language='en';}catch{}
try{if(typeof location!=='undefined'&&['hu','en'].includes(new URL(location.href).searchParams.get('lang')))language=new URL(location.href).searchParams.get('lang');}catch{}
export function getLanguage(){return language;}
export function translate(source,lang=language){
 if(lang!=='en'||typeof source!=='string')return source;
 const key=source.trim();let value=en[key];
 if(value===undefined){
  let m;
  if((m=key.match(/^(\d+) épület · (.+) szerkezet · (\d+) saját negyed$/)))value=`${m[1]} buildings · ${translate(m[2],lang)} layout · ${m[3]} custom districts`;
  else if((m=key.match(/^(\d+) terem · (.+) elrendezés · 1 mező = 5 láb$/)))value=`${m[1]} rooms · ${translate(m[2],lang)} layout · 1 square = 5 feet`;
  else if((m=key.match(/^(\d+) opció$/)))value=`${m[1]} options`;
  else if((m=key.match(/^GENERÁTOR V(\d+)$/)))value=`GENERATOR V${m[1]}`;
  else if((m=key.match(/^(VÁROS|DUNGEON) · (\d+) saját jelölés$/)))value=`${m[1]==='VÁROS'?'CITY':'DUNGEON'} · ${m[2]} custom markers`;
  else if((m=key.match(/^(.+) · privát$/)))value=`${translate(m[1],lang)} · private`;
  else if((m=key.match(/^(.+) hozzáadva\.$/)))value=`${translate(m[1],lang)} added.`;
  else if((m=key.match(/^(.+) hozzáadása$/)))value=`Add ${translate(m[1],lang).toLowerCase()}`;
  else if((m=key.match(/^(#[0-9a-f]+) szín$/i)))value=`${m[1]} color`;
  else if((m=key.match(/^(\d+) (?:pont|határpont).*$/)))value=`${m[1]} vertices · tap the first vertex or Finish.`;
  else if(key===key.toUpperCase()){const entry=Object.entries(en).find(([hu])=>hu.toUpperCase()===key);if(entry)value=entry[1].toUpperCase();}
 }
 if(value===undefined)return source;
 return source.slice(0,source.length-source.trimStart().length)+value+source.slice(source.trimEnd().length);
}
const originals=new WeakMap(),attributes=new WeakMap();
const protectedContent='svg,textarea,input,#map-render,#map-title,#map-seed,.place-name,.saved-card-title,.place-description,#place-details h3,[data-user-content]';
function applyLanguage(){
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_ELEMENT|NodeFilter.SHOW_TEXT,{acceptNode(node){if(node.nodeType===1)return node.matches(protectedContent)?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_SKIP;return NodeFilter.FILTER_ACCEPT;}});
 let node;while((node=walker.nextNode())){const current=node.nodeValue,old=originals.get(node),source=old&&current===old.last?old.source:current,last=translate(source);originals.set(node,{source,last});if(current!==last)node.nodeValue=last;}
 for(const element of document.querySelectorAll('[aria-label],[title],[placeholder]')){
  if(element.closest('svg,[data-user-content]'))continue;
  const saved=attributes.get(element)||{};
  for(const name of['aria-label','title','placeholder'])if(element.hasAttribute(name)){const current=element.getAttribute(name),old=saved[name],source=old&&current===old.last?old.source:current,last=translate(source);saved[name]={source,last};if(current!==last)element.setAttribute(name,last);}
  attributes.set(element,saved);
 }
}
export function setLanguage(value){
 language=value==='en'?'en':'hu';try{localStorage.setItem('crowcity-language',language);}catch{}
 const url=new URL(location.href);if(url.searchParams.has('lang')){url.searchParams.set('lang',language);history.replaceState(null,'',url);}
 document.documentElement.lang=language;document.title=language==='en'?'CrowCity — Map Workshop':'CrowCity — Térképműhely';document.getElementById('language').value=language;
 document.dispatchEvent(new CustomEvent('crowcity-language'));applyLanguage();
}
export function initI18n(){
 document.getElementById('language').addEventListener('change',event=>setLanguage(event.target.value));
 let queued=false;const observer=new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;applyLanguage();});});
 observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','title','placeholder']});
 setLanguage(language);
}
